    State(state): State<AppState>,
    ValidatedJson(req): ValidatedJson<ResetPasswordRequest>,
) -> Result<Json<MessageResponse>> {
    let db = state.require_db()?;

    let token_hash = crate::services::auth::hash_reset_token(&req.token);

    let user_id = crate::repo::user::find_valid_reset_token(db, &token_hash)
        .await?
        .ok_or_else(|| AppError::validation("invalid or expired reset token"))?;

    // Hash the new password and update
    let new_hash = crate::services::auth::hash_password(&req.new_password)?;
    crate::repo::user::set_password_hash(db, user_id, &new_hash).await?;

    // Mark the token as used
    crate::repo::user::mark_reset_token_used(db, &token_hash).await?;

pub async fn change_password(
    auth: AuthUser,
    State(state): State<AppState>,
    ValidatedJson(req): ValidatedJson<ChangePasswordRequest>,
) -> Result<Json<MessageResponse>> {
    let db = state.require_db()?;
    let user = crate::repo::user::find_by_id(db, auth.user_id).await?;

    let password_hash = user
        .password_hash
        .as_deref()
        .ok_or_else(|| AppError::validation("password not set"))?;
    if !crate::services::auth::verify_password(&req.current_password, password_hash)? {
        return Err(AppError::unauthorized("current password is incorrect"));
    }

    let new_hash = crate::services::auth::hash_password(&req.new_password)?;
    crate::repo::user::set_password_hash(db, auth.user_id, &new_hash).await?;

